#include <string.h>
int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long k;if(scanf("%lld",&k)!=1)return 1;long long best=a[0],d1,d2;for(i=0;i<n;i++){d1=a[i]-k;if(d1<0)d1=-d1;d2=best-k;if(d2<0)d2=-d2;if(d1<d2||(d1==d2&&a[i]<best))best=a[i];}printf("%lld\n",best);return 0;}
